item.aggregated_output:
//! Headless session worker for the TUI (the former tui-worker.ts protocol).
//! One JSON request per line on stdin:  {"id": N, "method": "...", "params": {...}}
//! One JSON response per line:          {"id": N, "result": ...} | {"id": N, "error": "..."}
//! Async pushes (no id):                {"push": "delta", "run_id", "agent_id", "text"}
//!
//! The worker owns the Runtime; the Rust TUI is a pure client of this protocol.

use crate::session::{open_session, OpenOptions, OpenedSession};
use crate::sessions::{archive_session, delete_session, list_sessions, new_session_id, session_paths};
use crate::scripted::Step;
use crate::{config, VERSION};
use serde_json::{json, Value as Json};
use std::collections::HashMap;
use std::io::{BufRead, Write};
use std::path::PathBuf;
use std::sync::{Arc, Mutex};

fn out(message: &Json) {
    let stdout = std::io::stdout();
    let mut handle = stdout.lock();
    let _ = writeln!(handle, "{message}");
    let _ = handle.flush();
}

struct Worker {
    opened: Mutex<Option<Arc<OpenedSession>>>,
    cwd: Mutex<Option<PathBuf>>,
    full_auto: Mutex<bool>,
    team: Mutex<Option<String>>,
}

impl Worker {
    fn new() -> Self {
        Self {
            opened: Mutex::new(None),
            cwd: Mutex::new(None),
            full_auto: Mutex::new(false),
            team: Mutex::new(None),
        }
    }

    fn current(&self) -> Result<Arc<OpenedSession>, String> {
        self.opened
            .lock()
            .unwrap()
            .clone()
            .ok_or_else(|| "no open session".to_string())
    }

    fn close_current(&self) {
        let current = self.opened.lock().unwrap().take();
        if let Some(current) = current {
            current.close();
        }
    }

    fn open(&self, params: &Json) -> Result<Json, String> {
        self.close_current();
        let cwd = params
            .get("cwd")
            .and_then(|v| v.as_str())
            .map(PathBuf::from)
            .or_else(|| std::env::current_dir().ok());
        let full_auto = params.get("fullAuto").and_then(|v| v.as_bool()).unwrap_or(false);
        let team = params.get("team").and_then(|v| v.as_str()).map(str::to_string);
        *self.cwd.lock().unwrap() = cwd.clone();
        *self.full_auto.lock().unwrap() = full_auto;
        *self.team.lock().unwrap() = team.clone();

        let initial_spec = match &team {
            Some(path) => Some(config::load_spec_file(std::path::Path::new(path))?),
            // fork passes the source session's live spec directly (D-26)
            None => params.get("initial_spec").cloned(),
        };
        let scripts: Option<HashMap<String, Vec<Step>>> = params
            .get("scripts")
            .and_then(|v| v.as_object())
            .map(|map| {
                map.iter()
                    .map(|(agent, steps)| {
                        let parsed = steps
                            .as_array()
                            .map(|array| array.iter().map(Step::from_json).collect::<Result<Vec<_>, _>>())
                            .unwrap_or(Ok(vec![]));
                        Ok((agent.clone(), parsed?))
                    })
                    .collect::<Result<HashMap<_, _>, String>>()
            })
            .transpose()?;

        let opened = open_session(OpenOptions {
            cwd,
            session_id: params.get("resume").and_then(|v| v.as_str()).map(str::to_string),
            full_auto,
            initial_spec,
            catalog: None,
            scripts,
        })?;
        let sink_session = opened.session_id.clone();
        opened.runtime.notify.set_stream_sink(Box::new(move |run_id, agent_id, text| {
            let _ = sink_session;
            out(&json!({"push": "delta", "run_id": run_id, "agent_id": agent_id, "text": text}));
        }));
        opened.runtime.start();
        *self.opened.lock().unwrap() = Some(opened.clone());
        Ok(json!({
            "session_id": opened.session_id,
            "state_dir": config::state_dir().to_string_lossy(),
            "sessions_dir": config::sessions_dir().to_string_lossy(),
            "user_config_path": config::user_config_path().to_string_lossy(),
            "catalog": opened.catalog(),
        }))
    }

    fn handle(&self, method: &str, params: &Json) -> Result<Json, String> {
        match method {
            "ping" => Ok(json!({"worker": VERSION})),
            "open" => self.open(params),
            "call" => {
                let opened = self.current()?;
                let inner = params.get("method").and_then(|v| v.as_str()).ok_or("method required")?;
                opened.runtime.core.call_in_session(inner, params.get("params").cloned().unwrap_or(json!({})))
            }
            "submit" => {
                let opened = self.current()?;
                let mut action = params.get("action").cloned().unwrap_or(json!({}));
                let Some(object) = action.as_object_mut() else { return Err("action must be an object".into()) };
                object.insert("session_id".into(), json!(opened.session_id));
                object.entry("actor_id").or_insert(json!("user"));
                let action: teamagents_core::models::TeamAction =
                    serde_json::from_value(action).map_err(|e| format!("bad action: {e}"))?;
                let receipt = opened.runtime.submit(action)?;
                Ok(serde_json::to_value(receipt).map_err(|e| e.to_string())?)
            }
            "user_message" => {
                let opened = self.current()?;
                let text = params.get("text").and_then(|v| v.as_str()).unwrap_or("").to_string();
                let supplement = params.get("supplement").and_then(|v| v.as_bool()).unwrap_or(false);
                let receipt = opened.runtime.user_message(&text, supplement)?;
                Ok(serde_json::to_value(receipt).map_err(|e| e.to_string())?)
            }
            "list_sessions" => {
                let cwd = params
                    .get("cwd")
                    .and_then(|v| v.as_str())
                    .map(PathBuf::from)
                    .or_else(|| self.cwd.lock().unwrap().clone());
                Ok(json!({"sessions": list_sessions(cwd.as_deref(), true, None)}))
            }
            "switch_session" => {
                let session_id = params.get("session_id").and_then(|v| v.as_str()).unwrap_or("").to_string();
                self.open(&json!({
                    "cwd": self.cwd.lock().unwrap().clone().map(|p| p.to_string_lossy().into_owned()),
                    "resume": session_id,
                    "fullAuto": *self.full_auto.lock().unwrap(),
                    "team": self.team.lock().unwrap().clone(),
                }))
            }
            "new_session" => {
                let cwd = self.cwd.lock().unwrap().clone().unwrap_or_else(|| PathBuf::from("."));
                self.open(&json!({
                    "cwd": self.cwd.lock().unwrap().clone().map(|p| p.to_string_lossy().into_owned()),
                    "resume": new_session_id(&cwd),
                    "fullAuto": *self.full_auto.lock().unwrap(),
                    "team": self.team.lock().unwrap().clone(),
                }))
            }
            "archive_session" => {
                let session_id = params.get("session_id").and_then(|v| v.as_str()).unwrap_or("").to_string();
                let was_current = self.opened.lock().unwrap().as_ref().map(|o| o.session_id == session_id).unwrap_or(false);
                if was_current {
                    self.close_current();
                }
                let target = archive_session(&session_id, None)?;
                Ok(json!({"was_current": was_current, "target": target}))
            }
            "delete_session" => {
                let session_id = params.get("session_id").and_then(|v| v.as_str()).unwrap_or("").to_string();
                let was_current = self.opened.lock().unwrap().as_ref().map(|o| o.session_id == session_id).unwrap_or(false);
                if was_current {
                    self.close_current();
                }
                delete_session(&session_id, None)?;
                Ok(json!({"was_current": was_current}))
            }
            "usage" => Ok(self.current()?.usage_report()),
            // feature 5 (/model): effective model/effort per member
            "model" => Ok(self.current()?.model_report()),
            "set_model" => {
                let opened = self.current()?;
                let agent_id = params.get("agent_id").and_then(|v| v.as_str()).ok_or("agent_id required")?;
                let model = params.get("model").and_then(|v| v.as_str()).map(str::to_string);
                let effort = params.get("effort").and_then(|v| v.as_str()).map(str::to_string);
                let profile = params.get("profile").and_then(|v| v.as_str()).map(str::to_string);
                if profile.is_some() { opened.set_model_selection(agent_id, profile, model, effort) }
                else { opened.set_model_override(agent_id, model, effort) }
            }
            // D-26 rewind/fork (pi-style tree history, leader conversation)
            "rewind_points" => Ok(self.current()?.rewind_points()?),
            "rewind" => {
                let node = params.get("node_id").and_then(|v| v.as_str()).map(str::to_string);
                Ok(self.current()?.rewind(node)?)
            }
            "fork_session" => {
                let opened = self.current()?;
                let state = opened.core.call_in_session("state", json!({"include_events": false}))?;
                // fork while a turn is in flight would cancel it on close and
                // BLOCK its task (see AGENTS.md operations notes)
                let any_active = state
                    .get("runs")
                    .and_then(|v| v.as_array())
                    .cloned()
                    .unwrap_or_default()
                    .into_iter()
                    .any(|r| r.get("status").and_then(|v| v.as_str()).map(|s| s == "QUEUED" || s == "RUNNING").unwrap_or(false));
                if any_active {
                    return Err("有回合进行中，等它结束后再 fork".into());
                }
                let leader = state.get("leader_id").and_then(|v| v.as_str()).unwrap_or("").to_string();
                let spec = state.get("spec").cloned().ok_or("no spec")?;
                let cwd = self.cwd.lock().unwrap().clone().unwrap_or_else(|| PathBuf::from("."));
                // fork = same spec + leader's history tree, fresh team state
                // (tasks/runs/events are facts of the source session and are
                // NOT copied; file changes are never rolled back — D-26)
                let new_id = new_session_id(&cwd);
                let tree_src = session_paths(&opened.session_id).base.join("members").join(&leader).join("chat_tree.json");
                if tree_src.is_file() {
                    let dest_dir = session_paths(&new_id).base.join("members").join(&leader);
                    std::fs::create_dir_all(&dest_dir).map_err(|e| e.to_string())?;
                    std::fs::copy(&tree_src, dest_dir.join("chat_tree.json")).map_err(|e| e.to_string())?;
                }
                let mut out = self.open(&json!({
                    "cwd": cwd.to_string_lossy(),
                    "resume": new_id,
                    "fullAuto": *self.full_auto.lock().unwrap(),
                    "team": Json::Null,
                    "initial_spec": spec,
                }))?;
                out["forked_from"] = json!(opened.session_id.clone());
                Ok(out)
            }
            "close" => {
                self.close_current();
                Ok(json!({"ok": true}))
            }
            other => Err(format!("unknown method {other}")),
        }
    }
}

pub fn serve() -> i32 {
    let worker = Worker::new();
    let stdin = std::io::stdin();
    for line in stdin.lock().lines() {
        let Ok(line) = line else { break };
        if line.trim().is_empty() {
            continue;
        }
        let Ok(request) = serde_json::from_str::<Json>(&line) else { continue };
        let id = request.get("id").cloned().unwrap_or(Json::Null);
        let method = request.get("method").and_then(|v| v.as_str()).unwrap_or("").to_string();
        let params = request.get("params").cloned().unwrap_or(json!({}));
        // Slow read-only discovery must not block cancellation, polling or close.
        if method == "discover_models" {
            match (worker.current(), params["provider"].as_str().map(str::to_string)) {
                (Ok(opened), Some(provider)) => { std::thread::spawn(move || {
                    match opened.discover_models(&provider) {
                        Ok(result) => out(&json!({"id":id, "result":result})),
                        Err(error) => out(&json!({"id":id, "error":error})),
                    }
                }); }
                (Err(error), _) => out(&json!({"id":id, "error":error})),
                (_, None) => out(&json!({"id":id, "error":"provider required"})),
            }
            continue;
        }
        match worker.handle(&method, &params) {
            Ok(result) => out(&json!({"id": id, "result": result})),
            Err(e) => out(&json!({"id": id, "error": e})),
        }
        if method == "close" {
            break;
        }
    }
    worker.close_current();
    0
}

//! Session bootstrap: paths + lock + core session,
//! member runners, runtime loop.

use crate::chat::ChatRunner;
use crate::codex::{CodexOptions, CodexRunner};
use crate::config::{expand_home, load_user_config_for, user_config_path};
use crate::core_client::CoreClient;
use crate::gateway::{ApprovalGate, PermissionPolicy, TurnControl};
use crate::runtime::{AgentRunner, Notify, RunnerFactory, Runtime, RuntimeLimits, ToolExecutor};
use crate::scripted::{BarrierRegistry, ScriptedMember, Step};
use crate::sessions::{acquire_session_lock, new_session_id, session_paths, SessionLock};
use serde_json::{json, Value as Json};
use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use teamagents_core::models::{AgentSpec, ModelProfile, RuntimeKind, TeamAction, UserConfig};

pub const LEADER_INSTRUCTIONS: &str = "You are the Leader of a team of agents. Understand the user's goal, decide
whether to work alone or build a team, delegate with assign_task, coordinate
with send_message, and report completion with signal_done. Keep task descriptions
specific, include acceptance criteria, and never bypass runtime permissions.
When creating a member via apply_topology_patch add_agent, you may omit
model_profile (a per-member profile is auto-created from your current model),
or set it to a model id (reuses your connection) or an existing profile name.
";

pub fn default_leader_spec(profile: &str, tools: &[&str]) -> Json {
    json!({
        "leader_id": "leader",
        "agents": [{
            "id": "leader",
            "name": "Leader",
            "role": "leader",
            "runtime_kind": "deepagents",
            "instructions": LEADER_INSTRUCTIONS,
            "model_profile": profile,
            "tool_bindings": tools,
        }],
        "shared_spaces": [{"id": "main", "readers": ["leader"], "writers": ["leader"]}],
    })
}

pub struct OpenOptions {
    pub cwd: Option<PathBuf>,
    pub session_id: Option<String>,
    pub full_auto: bool,
    pub initial_spec: Option<Json>,
    pub catalog: Option<UserConfig>,
    /// Worker/test mode: deterministic members instead of model backends.
    pub scripts: Option<HashMap<String, Vec<Step>>>,
}

impl Default for OpenOptions {
    fn default() -> Self {
        Self { cwd: None, session_id: None, full_auto: false, initial_spec: None, catalog: None, scripts: None }
    }
}

/// Per-agent usage snapshot source, registered when the runner is built
/// (the AgentRunner trait stays usage-agnostic; runtime.rs untouched).
type UsageProbe = Box<dyn Fn() -> Json + Send + Sync>;
type UsageProbes = Arc<Mutex<HashMap<String, UsageProbe>>>;

/// Feature 5 (/model): per-member session-level model/effort override. Either
/// field left None falls back to the member's ModelProfile. Persisted per
/// session (D-29), so a reopened session keeps its /model choices.
#[derive(Clone, Debug, Default, serde::Serialize, serde::Deserialize)]
pub struct ModelOverride {
    pub profile: Option<String>,
    pub model: Option<String>,
    pub effort: Option<String>,
}
pub type ModelOverrides = Arc<Mutex<HashMap<String, ModelOverride>>>;

/// `sessions/<id>/model_overrides.json` (D-29).
fn overrides_path(session_id: &str) -> PathBuf {
    session_paths(session_id).base.join("model_overrides.json")
}

/// `sessions/<id>/profiles.json` — per-session model profiles auto-created when
/// the Leader adds a member without naming an existing profile (D-30).
/// Within one session each member maps to its own profile; another session gets
/// another set.
fn profiles_path(session_id: &str) -> PathBuf {
    session_paths(session_id).base.join("profiles.json")
}

fn load_session_profiles(session_id: &str) -> HashMap<String, ModelProfile> {
    let Ok(text) = std::fs::read_to_string(profiles_path(session_id)) else { return HashMap::new() };
    serde_json::from_str(&text).unwrap_or_default()
}

/// Atomic rewrite of `profiles.json` (tmp + rename).
fn save_session_profiles(session_id: &str, profiles: &HashMap<String, ModelProfile>) -> Result<(), String> {
    let path = profiles_path(session_id);
    let tmp = path.with_extension("tmp");
    let text = serde_json::to_string_pretty(profiles).map_err(|e| e.to_string())?;
    std::fs::write(&tmp, text)
        .and_then(|_| std::fs::rename(&tmp, &path))
        .map_err(|e| format!("persist session profiles: {e}"))
}

/// Load persisted overrides, dropping entries that no longer validate against
/// the current spec/catalog (members or profiles may have changed since).
fn load_model_overrides(session_id: &str, catalog: &UserConfig, agents: &[AgentSpec]) -> HashMap<String, ModelOverride> {
    let Ok(text) = std::fs::read_to_string(overrides_path(session_id)) else { return HashMap::new() };
    let parsed: HashMap<String, ModelOverride> = serde_json::from_str(&text).unwrap_or_default();
    parsed
        .into_iter()
        .filter(|(id, ov)| {
            let Some(agent) = agents.iter().find(|a| &a.id == id) else { return false };
            let Some(profile) = catalog.models.get(ov.profile.as_ref().unwrap_or(&agent.model_profile)) else { return false };
            if ov.profile.is_some() && agent.runtime_kind == RuntimeKind::Codex && profile.protocol != "openai" {
                return false;
            }
            ov.effort.as_ref().is_none_or(|e| model_efforts(&profile.protocol).contains(&e.as_str()))
        })
        .collect()
}

pub struct OpenedSession {
    pub runtime: Arc<Runtime>,
    pub core: Arc<CoreClient>,
    pub session_id: String,
    pub cwd: PathBuf,
    pub catalog: UserConfig,
    /// Session-scoped auto-created profiles (D-30); win over user config names.
    session_profiles: Arc<Mutex<HashMap<String, ModelProfile>>>,
    usage_probes: UsageProbes,
    model_overrides: ModelOverrides,
    /// Held for the session's lifetime; dropping it (normal close or any error
    /// path during open) releases the session for other processes.
    lock: Mutex<Option<SessionLock>>,
}

impl OpenedSession {
    pub fn catalog(&self) -> Json {
        let mut merged = self.catalog.clone();
        merged.models.extend(self.session_profiles.lock().unwrap().clone());
        serde_json::to_value(&merged).unwrap_or(Json::Null)
    }

    /// Session profiles shadow user-config profiles of the same name (D-30).
    fn lookup_model(&self, name: &str) -> Option<ModelProfile> {
        self.session_profiles
            .lock()
            .unwrap()
            .get(name)
            .cloned()
            .or_else(|| self.catalog.models.get(name).cloned())
    }

    /// User config models + session profiles (session wins), sorted by name.
    fn merged_models(&self) -> std::collections::BTreeMap<String, ModelProfile> {
        let mut merged: std::collections::BTreeMap<String, ModelProfile> =
            self.catalog.models.clone().into_iter().collect();
        merged.extend(self.session_profiles.lock().unwrap().clone());
        merged
    }

    /// Per-agent token usage for /status (worker "usage" method, CLI status).
    /// Session-memory counters only — a restarted session starts from zero.
    pub fn usage_report(&self) -> Json {
        let agents = self
            .core
            .state()
            .ok()
            .and_then(|state| state.get("spec").and_then(|s| s.get("agents")).cloned())
            .and_then(|agents| agents.as_array().cloned())
            .unwrap_or_default();
        let probes = self.usage_probes.lock().unwrap();
        let report: Vec<Json> = agents
            .iter()
            .map(|agent| {
                let id = agent.get("id").and_then(|v| v.as_str()).unwrap_or("");
                let ov = self.model_overrides.lock().unwrap().get(id).cloned().unwrap_or_default();
                let profile_name = ov.profile.as_deref().unwrap_or_else(|| agent.get("model_profile").and_then(|v| v.as_str()).unwrap_or(""));
                let profile = self.lookup_model(profile_name);
                let usage = probes.get(id).map(|probe| probe());
                // codex reports its own window; the profile wins when set
                let context_window = profile
                    .as_ref()
                    .and_then(|p| p.context_window)
                    .or_else(|| usage.as_ref().and_then(|u| u.get("codex_context_window")).and_then(Json::as_u64));
                json!({
                    "agent_id": id,
                    "name": agent.get("name").and_then(|v| v.as_str()).unwrap_or(id),
                    "model_profile": profile_name,
                    "model": ov.model.as_deref().or_else(|| profile.as_ref().map(|p| p.model.as_str())),
                    "context_window": context_window,
                    "usage": usage,
                })
            })
            .collect();
        json!({"session_id": self.session_id, "agents": report})
    }

    /// (leader_id, current conversation thread) for rewind/fork (D-26).
    /// The thread is `ctx:{agent}:{context_epoch}` (control.rs::context_ref).
    fn leader_thread(&self) -> Result<(String, String), String> {

//! D-26 fork/rewind over the worker protocol (pi-style tree history).

use serde_json::{json, Value as Json};
use std::io::{BufReader, Write};
use std::process::{Command, Stdio};

fn state_home(tag: &str) -> std::path::PathBuf {
    let dir = std::env::temp_dir().join(format!("ta-fork-{tag}-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    dir
}

fn call(child: &mut std::process::Child, stdin: &mut impl Write, id: u64, method: &str, params: Json) -> Json {
    writeln!(stdin, "{}", json!({"id": id, "method": method, "params": params})).unwrap();
    stdin.flush().unwrap();
    let stdout = child.stdout.as_mut().unwrap();
    let mut line = String::new();
    loop {
        line.clear();
        use std::io::BufRead;
        let mut reader = std::io::BufReader::new(&mut *stdout);
        // read until the response with our id (skip pushes)
        loop {
            line.clear();
            if reader.read_line(&mut line).unwrap() == 0 {
                panic!("worker exited");
            }
            let message: Json = serde_json::from_str(line.trim()).unwrap_or(json!({}));
            if message.get("push").is_some() {
                continue;
            }
            if message.get("id").and_then(|v| v.as_u64()) == Some(id) {
                if let Some(error) = message.get("error").and_then(|v| v.as_str()) {
                    panic!("{method} failed: {error}");
                }
                return message.get("result").cloned().unwrap_or(Json::Null);
            }
        }
    }
}

#[test]
fn fork_carries_spec_and_leader_tree_but_not_team_facts() {
    let home = state_home("fork");
    let mut child = Command::new(env!("CARGO_BIN_EXE_teamagents"))
        .arg("serve")
        .env("XDG_STATE_HOME", &home)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit())
        .spawn()
        .expect("spawn engine");
    let mut stdin = child.stdin.take().unwrap();

    let opened = call(&mut child, &mut stdin, 1, "open", json!({"cwd": "/tmp", "scripts": {"leader": [["end"]]}}));
    let old_id = opened.get("session_id").and_then(|v| v.as_str()).unwrap().to_string();

    // fabricate a leader history tree as a finished turn would have left it
    let tree = json!({
        "user-dialog-ignore": {"nodes": [], "leaf": null},
        "ctx:leader:1": {"nodes": [
            {"id": "n1", "parent": null, "message": {"role": "user", "content": "u1"}},
            {"id": "n2", "parent": "n1", "message": {"role": "assistant", "content": "a1"}}
        ], "leaf": "n2"}
    });
    let member_dir = home.join("teamagents/sessions").join(&old_id).join("members/leader");
    std::fs::create_dir_all(&member_dir).unwrap();
    std::fs::write(member_dir.join("chat_tree.json"), tree.to_string()).unwrap();

    // rewind without a live runner is a clean error, not a panic
    let rewind = {
        let id = 2u64;
        writeln!(stdin, "{}", json!({"id": id, "method": "rewind", "params": {"node_id": null}})).unwrap();
        stdin.flush().unwrap();
        read_reply(&mut child, id)
    };
    assert!(rewind.get("error").and_then(|v| v.as_str()).is_some(), "rewind without runner must fail: {rewind}");

    let forked = call(&mut child, &mut stdin, 3, "fork_session", json!({}));
    let new_id = forked.get("session_id").and_then(|v| v.as_str()).unwrap().to_string();
    assert_ne!(new_id, old_id);
    assert_eq!(forked.get("forked_from").and_then(|v| v.as_str()), Some(old_id.as_str()));

    // the leader tree file came along; team facts (tasks/runs) did not
    let copied = std::fs::read_to_string(home.join("teamagents/sessions").join(&new_id).join("members/leader/chat_tree.json")).unwrap();
    assert!(copied.contains("u1"), "tree not copied: {copied}");
    let state = call(&mut child, &mut stdin, 4, "call", json!({"method": "state", "params": {"session_id": new_id}}));
    let tasks = state.get("tasks").and_then(|v| v.as_array()).cloned().unwrap_or_default();
    assert!(tasks.is_empty(), "fork must start with fresh team state");

    drop(stdin);
    let _ = child.kill();
    let _ = child.wait();
}

fn read_reply(child: &mut std::process::Child, id: u64) -> Json {
    use std::io::BufRead;
    let stdout = child.stdout.as_mut().unwrap();
    let mut reader = BufReader::new(stdout);
    let mut line = String::new();
    loop {
        line.clear();
        if reader.read_line(&mut line).unwrap() == 0 {
            panic!("worker exited");
        }
        let message: Json = serde_json::from_str(line.trim()).unwrap_or(json!({}));
        if message.get("push").is_none() && message.get("id").and_then(|v| v.as_u64()) == Some(id) {
            return message;
        }
    }
}

    fn leader_thread(&self) -> Result<(String, String), String> {
        let state = self.core.call_in_session("state", json!({"include_events": false}))?;
        let leader = state
            .get("leader_id")
            .and_then(|v| v.as_str())
            .ok_or("no leader")?
            .to_string();
        let epoch = state
            .get("agents")
            .and_then(|v| v.as_array())
            .and_then(|agents| agents.iter().find(|a| a.get("id").and_then(|v| v.as_str()) == Some(leader.as_str())))
            .and_then(|a| a.get("context_epoch"))
            .and_then(|v| v.as_i64())
            .unwrap_or(0);
        Ok((leader.clone(), format!("ctx:{leader}:{epoch}")))
    }

    /// Rewind targets on the leader's conversation (user inputs, newest first).
    pub fn rewind_points(&self) -> Result<Json, String> {
        let (leader, thread) = self.leader_thread()?;
        let points = self
            .runtime
            .runner(&leader)
            .map(|r| r.rewind_points(&thread))
            .unwrap_or_default();
        Ok(json!({"agent_id": leader, "thread": thread, "points": points}))
    }

    /// Move the leader conversation's live tip (`node_id`, None = empty).
    /// Refused while the leader has an active turn: the in-flight tail would
    /// graft onto the rewound tip (ponytail ceiling, chat.rs run_segment).
    pub fn rewind(&self, node_id: Option<String>) -> Result<Json, String> {
        let (leader, thread) = self.leader_thread()?;
        let state = self.core.call_in_session("state", json!({"include_events": false}))?;
        let busy = state
            .get("runs")
            .and_then(|v| v.as_array())
            .cloned()
            .unwrap_or_default()
            .into_iter()
            .any(|r| {
                r.get("agent_id").and_then(|v| v.as_str()) == Some(leader.as_str())
                    && r.get("status").and_then(|v| v.as_str()).map(|s| s == "QUEUED" || s == "RUNNING").unwrap_or(false)
            });
        if busy {
            return Err("leader 回合进行中，等它结束后再 rewind".into());
        }
        let runner = self.runtime.runner(&leader).ok_or("leader 还没有运行器（尚未有过回合）")?;
        let depth = runner.rewind(&thread, node_id.as_deref())?;
        Ok(json!({"agent_id": leader, "thread": thread, "depth": depth}))
    }

    fn spec_agents(&self) -> Result<Vec<AgentSpec>, String> {
        let state = self.core.state()?;
        let agents = state.get("spec").and_then(|s| s.get("agents")).cloned().unwrap_or(Json::Null);
        serde_json::from_value(agents).map_err(|e| format!("bad spec agents: {e}"))
    }

    /// What one member's next turn would run with: override fields win, the
    /// rest falls back to the profile (codex effort defaults to the runner's
    /// built-in "xhigh").
    fn effective_model(&self, agent: &AgentSpec) -> Json {
        let ov = self.model_overrides.lock().unwrap().get(&agent.id).cloned();
        let profile_name = ov.as_ref().and_then(|o| o.profile.as_ref()).unwrap_or(&agent.model_profile);
        let profile = self.lookup_model(profile_name);
        let (o_model, o_effort) = ov.as_ref().map(|o| (o.model.clone(), o.effort.clone())).unwrap_or_default();
        let model = o_model.or_else(|| profile.as_ref().map(|p| p.model.clone()));
        let effort = o_effort.or_else(|| {
            if agent.runtime_kind == RuntimeKind::Codex {
                Some("xhigh".into())
            } else {
                profile.as_ref().and_then(profile_effort).map(str::to_string)
            }
        });
        json!({
            "agent_id": agent.id,
            "name": agent.name,
            "runtime_kind": agent.runtime_kind,
            "model_profile": profile_name,
            "provider": profile.as_ref().map(|p| p.provider.as_str()),
            "model": model,
            "effort": effort,
            "overridden": ov.is_some(),
        })
    }

    /// Feature 5 (/model): switch one member's model / reasoning effort for
    /// this session; both None clears the override (profile default). The
    /// cached runner is invalidated so the change lands on the next turn.
    /// Overrides persist per session (D-29), never written back to the TeamSpec.
    pub fn set_model_override(&self, agent_id: &str, model: Option<String>, effort: Option<String>) -> Result<Json, String> {
        let profile = if model.is_none() && effort.is_none() { None } else {
            self.model_overrides.lock().unwrap().get(agent_id).and_then(|o| o.profile.clone())
        };
        self.set_model_selection(agent_id, profile, model, effort)
    }

    /// A selected profile owns the provider endpoint, auth reference and protocol.
    pub fn set_model_selection(&self, agent_id: &str, profile: Option<String>, model: Option<String>, effort: Option<String>) -> Result<Json, String> {
        let agents = self.spec_agents()?;
        let agent = agents
            .iter()
            .find(|a| a.id == agent_id)
            .ok_or_else(|| format!("unknown member {agent_id}"))?;
        let selected = match &profile {
            Some(name) => Some(self.lookup_model(name).ok_or_else(|| format!("unknown model profile {name}"))?),
            None => self.lookup_model(&agent.model_profile),
        };
        if profile.is_some() && agent.runtime_kind == RuntimeKind::Codex
            && selected.as_ref().is_some_and(|p| p.protocol != "openai") {
            return Err("Codex 成员需要支持 Responses API 的 OpenAI 兼容供应商".into());
        }
        if let Some(model) = &model {
            if model.trim().is_empty() {
                return Err("model must be a non-empty string".into());
            }
        }
        let effort = effort.map(|s| s.to_ascii_lowercase());
        if let Some(effort) = &effort {
            let choices = model_efforts(selected.as_ref().map(|p| p.protocol.as_str()).unwrap_or("openai"));
            if !choices.contains(&effort.as_str()) {
                return Err(format!("effort must be one of {}", choices.join("/")));
            }
        }
        {
            let mut overrides = self.model_overrides.lock().unwrap();
            if profile.is_none() && model.is_none() && effort.is_none() {
                overrides.remove(agent_id);
            } else {
                overrides.insert(agent_id.to_string(), ModelOverride { profile, model, effort });
            }
        }
        self.persist_model_overrides()?;
        self.runtime.drop_runner(agent_id);
        Ok(self.effective_model(agent))
    }

    /// `/model` with no args / worker "model": every member's effective values.
    pub fn model_report(&self) -> Json {
        let agents = self.spec_agents().unwrap_or_default();
        let merged = self.merged_models();
        let mut profiles: Vec<_> = merged.iter().collect();
        profiles.sort_by_key(|(name, p)| (&p.provider, &p.model, name.as_str()));
        json!({
            "session_id": self.session_id,
            "leader_id": self.core.state().ok().and_then(|s| s.get("leader_id").cloned()),
            "agents": agents.iter().map(|a| self.effective_model(a)).collect::<Vec<_>>(),
            "profiles": profiles.iter().map(|(name, p)| json!({
                "id": name, "provider": p.provider, "model": p.model, "protocol": p.protocol,
                "effort": profile_effort(p), "efforts": model_efforts(&p.protocol),
            })).collect::<Vec<_>>(),
        })
    }

    /// Read-only network discovery. The worker runs it outside its request loop.
    pub fn discover_models(&self, provider: &str) -> Result<Json, String> {
        let merged = self.merged_models();
        let profiles: Vec<_> = merged.iter().filter(|(_, p)| p.provider == provider).collect();
        if profiles.is_empty() { return Err(format!("unknown provider {provider}")); }
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        let mut seen = std::collections::HashSet::new();
        let mut models = vec![];
        let mut errors = vec![];
        for (name, profile) in profiles {
            let base = crate::chat::resolve_base_url(profile);
            if !seen.insert((base, profile.protocol.clone(), profile.api_key_env.clone())) { continue; }
            match fetch_model_ids(profile, deadline) {
                Ok(ids) => {
                    for model in ids {
                        // Keep explicitly configured models with their own options.
                        if merged.values().any(|p| p.provider == provider && p.model == model
                            && p.protocol == profile.protocol && p.api_key_env == profile.api_key_env
                            && crate::chat::resolve_base_url(p) == crate::chat::resolve_base_url(profile)) { continue; }
                        models.push(json!({"id": name, "provider": provider, "model": model,
                            "protocol": profile.protocol, "efforts": model_efforts(&profile.protocol), "discovered": true}));
                    }
                }
                Err(error) => errors.push(format!("{name}: {error}")),
            }
        }
        Ok(json!({"session_id":self.session_id, "provider":provider, "models":models, "errors":errors}))
    }

    /// Atomic rewrite of `model_overrides.json` (tmp + rename).
    fn persist_model_overrides(&self) -> Result<(), String> {
        let map = self.model_overrides.lock().unwrap();
        let path = overrides_path(&self.session_id);
        let tmp = path.with_extension("tmp");
        let text = serde_json::to_string_pretty(&*map).map_err(|e| e.to_string())?;
        std::fs::write(&tmp, text)
            .and_then(|_| std::fs::rename(&tmp, &path))
            .map_err(|e| format!("persist model overrides: {e}"))
    }

    pub fn close(&self) {
        self.runtime.close();
        let _ = self.lock.lock().unwrap().take();
    }
}

fn profile_effort(profile: &ModelProfile) -> Option<&str> {
    profile.generation_options.get("reasoning_effort").and_then(Json::as_str)
        .or_else(|| profile.generation_options.get("output_config")?.get("effort")?.as_str())
