pub fn open_session(opts: OpenOptions) -> Result<Arc<OpenedSession>, String> {
    // whitelist check first: a bad id must not create directories outside
    // the sessions root before the lock's own validation can refuse it
    if let Some(id) = &opts.session_id {
        crate::sessions::validate_session_id(id)?;
    }
    let cwd = match &opts.cwd {
        Some(cwd) => std::fs::canonicalize(cwd).unwrap_or_else(|_| cwd.clone()),
        None => std::env::current_dir().map_err(|e| e.to_string())?,
    };
    let catalog = match opts.catalog {
        Some(catalog) => catalog,
        None => load_user_config_for(&cwd)?,
    };
    let config_full_auto = crate::config::permission_mode_from_config()? == "full_auto";
    let full_auto = opts.full_auto || config_full_auto;
    let session_id = opts.session_id.clone().unwrap_or_else(|| new_session_id(&cwd));
    let paths = session_paths(&session_id);
    std::fs::create_dir_all(&paths.artifacts).map_err(|e| e.to_string())?;
    // dropped on every early return below, so a failed open never keeps the lock
    let lock = acquire_session_lock(&session_id)?;
    // resuming an archived id must fail loudly, not create an empty session
    // over it: the next archive of that fresh session would remove_dir_all the
    // original archived data. Checked under the lock: a concurrent archive
    // cannot move the directory between this check and the open below.
    let archived = crate::config::sessions_dir().join("archived").join(&session_id);
    if !paths.db.exists() && archived.exists() {
        // remove the ghost this open just created, but only the items it
        // created: with no team.db the active dir normally holds just our
        // artifacts/ + session.lock, and leaving them would let a later
        // archive_session overwrite the real archive with the ghost. If the
        // dir still holds anything else (e.g. member worktrees after team.db
        // was deleted by hand) rmdir fails and the content is left untouched
        // instead of being wiped by remove_dir_all (round 5, F3).
        drop(lock);
        let _ = std::fs::remove_dir_all(&paths.artifacts);
        let _ = std::fs::remove_file(&paths.lock);
        let _ = std::fs::remove_dir(&paths.base);
        return Err(format!(
            "session {session_id} is archived at {}; move it back to the sessions root to resume",
            archived.display()
        ));
    }
    let db = paths.db.to_string_lossy().into_owned();
    let core = CoreClient::open(&db, &session_id)?;

    let result = (|| -> Result<Arc<OpenedSession>, String> {
        let probe = core.call("state", json!({"session_id": session_id})).ok();
        let exists = probe
            .as_ref()
            .and_then(|state| state.get("session"))
            .map(|session| !session.is_null())
            .unwrap_or(false);
        if !exists {
            match core.call("create_session", json!({
                "session_id": session_id,
                "cwd": cwd.to_string_lossy(),
                "permissions_mode": if full_auto { "full_auto" } else { "approved_scope" },
            })) {
                Ok(_) => {
                    let spec = opts
                        .initial_spec
                        .clone()
                        .unwrap_or_else(|| default_leader_spec("leader_main", &["files", "shell", "web"]));
                    core.call("save_spec", json!({"session_id": session_id, "spec": spec}))?;
                }
                // the row exists but `state` failed: a session left without a
                // loadable spec by an earlier failed open. An explicitly given
                // spec repairs it; otherwise keep going so the real problem is
                // reported instead of a UNIQUE-constraint error.
                Err(e) if e.contains("UNIQUE") => {
                    if let Some(spec) = opts.initial_spec.clone() {
                        core.call("save_spec", json!({"session_id": session_id, "spec": spec}))?;
                    }
                }
                Err(e) => return Err(e),
            }
        } else if full_auto {
            if let Ok(state) = core.state() {
                if state.get("session").and_then(|s| s.get("permissions_mode")).and_then(|v| v.as_str()) != Some("full_auto") {
                    let receipt = core.submit(&TeamAction {
                        action_id: teamagents_core::models::new_id("mode"),
                        session_id: session_id.clone(),
                        actor_id: "user".into(),
                        run_id: None,
                        kind: teamagents_core::models::ActionKind::SetPermissionMode,
                        payload: json!({"mode": "full_auto"}),
                    })?;
                    if !receipt.ok {
                        return Err(receipt.error.unwrap_or_else(|| "cannot enable full auto".into()));
                    }
                }
            }
        }

        // keep validation (topology patches, member profiles) in sync with the
        // user config the engine loaded, plus this session's auto-created
        // member profiles (D-30)
        let session_profiles: Arc<Mutex<HashMap<String, ModelProfile>>> =
            Arc::new(Mutex::new(load_session_profiles(&session_id)));
        {
            let mut merged = catalog.clone();
            merged.models.extend(session_profiles.lock().unwrap().clone());
            core.call("set_catalog", json!({"session_id": session_id, "catalog": merged}))?;
        }
        let state = core.state()?;
        let mode = state
            .get("session")
            .and_then(|s| s.get("permissions_mode"))
            .and_then(|v| v.as_str())
            .unwrap_or("approved_scope");
        let policy = PermissionPolicy { mode: mode.to_string(), ..Default::default() };
        let approvals = ApprovalGate::new(core.clone(), policy);
        let agents: Vec<AgentSpec> = serde_json::from_value(state.get("spec").and_then(|s| s.get("agents")).cloned().unwrap_or(Json::Null))
            .map_err(|e| format!("bad team spec: {e}"))?;

        let barriers: BarrierRegistry = Arc::new(Mutex::new(HashMap::new()));
        let notify = Notify::new(core.clone());
        let usage_probes: UsageProbes = Arc::new(Mutex::new(HashMap::new()));
        let model_overrides: ModelOverrides =
            Arc::new(Mutex::new(load_model_overrides(&session_id, &catalog, &agents)));
        let make_runner: RunnerFactory = make_runner_factory(
            core.clone(),
            notify.clone(),
            approvals.clone(),
            catalog.clone(),
            session_id.clone(),
            cwd.clone(),
            opts.scripts.clone(),
            barriers,
            usage_probes.clone(),
            model_overrides.clone(),
            session_profiles.clone(),
        );

        let mut runners: HashMap<String, Arc<dyn AgentRunner>> = HashMap::new();
        for agent in &agents {
            let runner = make_runner(agent)?;
            runners.insert(agent.id.clone(), runner);
        }
        let executor = member_executor_factory(core.clone(), catalog.clone(), session_id.clone(), cwd.clone());
        let limits = RuntimeLimits {
            turn_active_timeout_s: state.get("limits").and_then(|l| l.get("turn_active_timeout_s")).and_then(|v| v.as_i64()).unwrap_or(1200),
            cancel_confirm_timeout_s: state.get("limits").and_then(|l| l.get("cancel_confirm_timeout_s")).and_then(|v| v.as_i64()).unwrap_or(60),
            max_model_steps_per_turn: state.get("limits").and_then(|l| l.get("max_model_steps_per_turn")).and_then(|v| v.as_i64()).unwrap_or(200),
            max_parallel_workers: state.get("limits").and_then(|l| l.get("max_parallel_workers")).and_then(|v| v.as_i64()).unwrap_or(8),
        };
        let runtime = Runtime::new(core.clone(), notify, approvals, executor, Some(make_runner), limits);
        runtime.set_topology_prepare(topology_prepare_hook(
            core.clone(),
            session_id.clone(),
            catalog.clone(),
            session_profiles.clone(),
            model_overrides.clone(),
        ));
        for (id, runner) in runners {
            runtime.add_runner(&id, runner);
        }
        Ok(Arc::new(OpenedSession {
            runtime,
            core,
            session_id,
            cwd,
            catalog,
            session_profiles,
            usage_probes,
            model_overrides,
            lock: Mutex::new(Some(lock)),
        }))
    })();
    result
}

/// D-30 hook: before an apply_topology_patch submit, every add_agent whose
/// model_profile is empty or names nothing configured gets a member-named
/// session profile cloned from the Leader's effective model config (a non-empty
/// unknown value is treated as a requested model id on the Leader's connection),
/// and the op is rewritten to point at it. Runs on the caller's thread.
fn topology_prepare_hook(
    core: Arc<CoreClient>,
    session_id: String,
    catalog: UserConfig,
    session_profiles: Arc<Mutex<HashMap<String, ModelProfile>>>,
    model_overrides: ModelOverrides,
) -> Arc<dyn Fn(&mut Json) -> Result<(), String> + Send + Sync> {
    Arc::new(move |payload: &mut Json| {

//! Session inventory / lock / archive / delete.

use crate::config::sessions_dir;
use rusqlite::{Connection, OpenFlags};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::{Mutex, OnceLock};
use std::time::{Duration, Instant};

pub struct SessionPaths {
    pub base: PathBuf,
    pub db: PathBuf,
    pub artifacts: PathBuf,
    pub locks: PathBuf,
    pub lock: PathBuf,
}

/// Same alphabet as agent ids (core models.rs::TeamSpec::validate). A session
/// id becomes a directory name; anything outside the whitelist never reaches
/// join(), so ".." cannot walk out of the sessions root.
pub(crate) fn validate_session_id(session_id: &str) -> Result<(), String> {
    if session_id.is_empty() || !session_id.chars().all(|c| c.is_alphanumeric() || c == '-' || c == '_') {
        return Err(format!("invalid session id {session_id:?}: use letters, digits, '-', '_'"));
    }
    Ok(())
}

pub fn session_paths(session_id: &str) -> SessionPaths {
    let base = sessions_dir().join(session_id);
    SessionPaths {
        db: base.join("team.db"),
        artifacts: base.join("artifacts"),
        locks: base.join("locks"),
        lock: base.join("session.lock"),
        base,
    }
}

pub fn default_session_id(cwd: &Path) -> String {
    let base = std::fs::canonicalize(cwd).unwrap_or_else(|_| cwd.to_path_buf());
    let hex = format!("{:x}", Sha256::digest(base.to_string_lossy().as_bytes()));
    format!("proj_{}", &hex[..12])
}

/// An flock held for as long as the session runs.
/// The kernel releases it when the process dies — kill -9 included — so a
/// crashed run never leaves the session "already running".
pub struct SessionLock {
    file: std::fs::File,
}

impl Drop for SessionLock {
    fn drop(&mut self) {
        let _ = self.file.unlock();
    }
}

/// Err means another process holds the session lock.
pub fn acquire_session_lock(session_id: &str) -> Result<SessionLock, String> {
    validate_session_id(session_id)?;
    let paths = session_paths(session_id);
    std::fs::create_dir_all(&paths.base).map_err(|e| e.to_string())?;
    let file = std::fs::OpenOptions::new()
        .create(true)
        .truncate(false)
        .read(true)
        .write(true)
        .open(&paths.lock)
        .map_err(|e| format!("cannot lock session {session_id}: {e}"))?;
    match file.try_lock() {
        Ok(()) => {}
        Err(std::fs::TryLockError::WouldBlock) => {
            let holder = std::fs::read_to_string(&paths.lock).unwrap_or_default();
            let holder = holder.trim();
            return Err(if holder.is_empty() {
                format!("session {session_id} is already running in another process")
            } else {
                format!("session {session_id} is already running (pid {holder})")
            });
        }
        Err(std::fs::TryLockError::Error(e)) => {
            return Err(format!("cannot lock session {session_id}: {e}"))
        }
    }
    // diagnostic only: the pid is not what makes the lock exclusive
    use std::io::Write;
    let _ = file.set_len(0);
    let _ = write!(&file, "{}", std::process::id());
    Ok(SessionLock { file })
}

pub fn is_session_locked(session_id: &str, base: Option<&Path>) -> bool {
    let lock = base.unwrap_or(&sessions_dir()).join(session_id).join("session.lock");
    let Ok(file) = std::fs::File::open(&lock) else { return false };
    matches!(file.try_lock(), Err(std::fs::TryLockError::WouldBlock))
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SessionInfo {
    #[serde(rename = "sessionId")]
