/// Wire the session as current: install its stream sink, start its runtime,
/// then release the previous one. Only a fully opened session reaches this,
/// so a failed open/switch/fork never closes the session the user has.
fn adopt(&self, opened: Arc<OpenedSession>, cwd: Option<PathBuf>, full_auto: bool, team: Option<String>) -> Json {
    let sink_session = opened.session_id.clone();
    opened.runtime.notify.set_stream_sink(Box::new(move |run_id, agent_id, text| {
        let _ = sink_session;
        out(&json!({"push": "delta", "run_id": run_id, "agent_id": agent_id, "text": text}));
    }));
    opened.runtime.start();
    self.close_current();
    *self.cwd.lock().unwrap() = cwd;
    *self.full_auto.lock().unwrap() = full_auto;
    *self.team.lock().unwrap() = team;
    let info = session_info(&opened);
    *self.opened.lock().unwrap() = Some(opened);
    info
}

fn open(&self, params: &Json) -> Result<Json, String> {
    let cwd = params
        .get("cwd")
        .and_then(|v| v.as_str())
        .map(PathBuf::from)
        .or_else(|| std::env::current_dir().ok());
    let full_auto = params.get("fullAuto").and_then(|v| v.as_bool()).unwrap_or(false);
    let team = params.get("team").and_then(|v| v.as_str()).map(str::to_string);
    let resume = params.get("resume").and_then(|v| v.as_str()).map(str::to_string);

    let initial_spec = match &team {
        Some(path) => Some(config::load_spec_file(std::path::Path::new(path))?),
        // fork passes the source session's live spec directly (D-26)
        None => params.get("initial_spec").cloned(),
    };
    let scripts: Option<HashMap<String, Vec<Step>>> = params
        .get("scripts")
        .and_then(|v| v.as_object())
        .map(|map| {
            map.iter()
                .map(|(agent, steps)| {
                    let parsed = steps
                        .as_array()
                        .map(|array| array.iter().map(Step::from_json).collect::<Result<Vec<_>, _>>())
                        .unwrap_or(Ok(vec![]));
                    Ok((agent.clone(), parsed?))
                })
                .collect::<Result<HashMap<_, _>, String>>()
        })
        .transpose()?;

    // Re-opening the session that is already open would fight its own
    // session lock; the live session already satisfies the request.
    if let (Some(target), Ok(current)) = (resume.as_deref(), self.current()) {
        if current.session_id == target {
