    let opened = open_session(OpenOptions {
        cwd: cwd.clone(),
        session_id: resume,
        full_auto,
        initial_spec,
        catalog: None,
        scripts,
    })?;
    Ok(self.adopt(opened, cwd, full_auto, team))
