    fn isolate(tag: &str) -> (std::sync::MutexGuard<'static, ()>, PathBuf, PathBuf) {
        let guard = crate::env_lock();
        let root = std::env::temp_dir().join(format!("ta-worker-{tag}-{}", std::process::id()));
